const text=v=>typeof v==='string'&&v.length>0&&v.length<=200&&!/[\x00-\x1f]/.test(v);
export const takeSourceTypes=[['actor','액터'],['player','플레이어'],['world','월드 액터']];
export function validTakeSources(sources){return Array.isArray(sources)&&new Set(sources.map(s=>s?.id)).size===sources.length&&sources.every(s=>s&&typeof s==='object'&&!Array.isArray(s)&&text(s.id)&&typeof s.enabled==='boolean'&&takeSourceTypes.some(([type])=>type===s.type)&&Object.keys(s).every(k=>['id','type','enabled',...s.type==='actor'?['actor']:[]].includes(k))&&(s.type!=='actor'||text(s.actor)));}
export function makeTakeSource(type,actor){if(!takeSourceTypes.some(([key])=>key===type))throw Error('녹화 소스 종류를 확인하세요.');const row={id:crypto.randomUUID(),type,enabled:true,...type==='actor'?{actor}:{}};if(!validTakeSources([row]))throw Error('녹화 액터를 선택하세요.');return row;}
export const recordableTakeActor=o=>!!o&&!['widget','component'].includes(o.kind)&&!o.destroying&&o.poolActive!==false;
export function resolveTakeSources(options,objects,{player=null}={}){
 const byId=new Map(objects.map(o=>[o.id,o]));
 if(options.targets!==undefined){const ids=options.targets;if(!Array.isArray(ids)||!ids.length||new Set(ids).size!==ids.length||ids.some(id=>!text(id)||!byId.has(id)))throw Error('녹화 대상 ID·중복을 확인하세요.');return {targets:[...ids],bindings:[]};}
 if(!validTakeSources(options.sources))throw Error('녹화 대상 또는 소스 목록을 지정하세요.');
 const targets=new Set(),bindings=[];let worldIds;for(const source of options.sources){if(!source.enabled)continue;const ids=source.type==='world'?(worldIds??=objects.filter(recordableTakeActor).map(o=>o.id)):[source.type==='player'?player:source.actor];if(!ids.length||ids.some(id=>!recordableTakeActor(byId.get(id))))throw Error('녹화 소스가 연결되지 않았어요: '+source.type+' · '+(source.actor||source.id));for(const id of ids)targets.add(id);bindings.push({id:source.id,type:source.type,targets:[...ids]});}
 if(!targets.size)throw Error('활성 녹화 소스가 없어요.');return {targets:[...targets],sources:structuredClone(options.sources),bindings};
}
export function takeSourceInput(input,current){const index=Number(input.dataset.takeSourceIndex),field=input.dataset.takeSourceField;if(!Number.isInteger(index)||!current[index]||!['actor','enabled'].includes(field))return null;const next=structuredClone(current);next[index][field]=field==='enabled'?input.checked:input.value;if(!validTakeSources(next))throw Error('녹화 소스를 확인하세요.');return next;}
export function takeSourceAction(button,current,element,world={}){const next=structuredClone(current??[]),objects=(world.objects||[]).filter(recordableTakeActor);if(button.hasAttribute('data-take-source-remove')){const i=Number(button.dataset.takeSourceRemove);if(!Number.isInteger(i)||!next[i])throw Error('삭제할 소스를 확인하세요.');next.splice(i,1);}else if(button.hasAttribute('data-take-source-add')){const type=element.querySelector('[data-take-source-type]').value;next.push(makeTakeSource(type,objects.find(o=>o.id===world.selected)?.id||objects[0]?.id));}else if(button.hasAttribute('data-take-source-selection')){const selected=new Set(world.selection??(world.selected?[world.selected]:[])),rows=objects.filter(o=>selected.has(o.id));if(!rows.length)throw Error('아웃라이너에서 녹화할 액터를 선택하세요.');for(const o of rows)if(!next.some(s=>s.type==='actor'&&s.actor===o.id))next.push(makeTakeSource('actor',o.id));}else return null;return next;}
